package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Stream;
import java.util.zip.ZipInputStream;
import org.jlinalg.sequence.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

/** Independent native statistics against actual current-package and literal historical motif controls. */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
public class SignacMotifEnrichmentTest {
    @TempDir static Path root;
    private Map<String,Object> cases,original;
    private final AtomicInteger files=new AtomicInteger();
    @BeforeAll void fixture()throws Exception{
        byte[] raw;try(var in=getClass().getResourceAsStream("/org/jlinalg/sequence/signac-motifs/original-controls.zip")){assertNotNull(in);raw=in.readAllBytes();}
        assertEquals("58da6ab3705620b20dce55bc651e101ee58a3205097392e1b4d4cba1699485ad",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw)));
        try(var zip=new ZipInputStream(new ByteArrayInputStream(raw))){java.util.zip.ZipEntry e;while((e=zip.getNextEntry())!=null){Path path=root.resolve(e.getName()).normalize();assertTrue(path.startsWith(root));Files.createDirectories(path.getParent());Files.write(path,zip.readAllBytes());}}
        cases=object(SimpleJson.parse(Files.readString(root.resolve("cases.json"),StandardCharsets.UTF_8)));original=object(SimpleJson.parse(Files.readString(root.resolve("original.json"),StandardCharsets.UTF_8)));
    }
    @TestFactory Stream<DynamicTest> fullOriginalStatistics(){List<DynamicTest> tests=new ArrayList<>();for(Object value:list(original.get("results"))){var record=object(value);var result=object(object(record.get("result")).get("value"));if(result.containsKey("error"))continue;for(boolean parsed:new boolean[]{false,true})tests.add(DynamicTest.dynamicTest(text(record,"profile")+"/"+text(record,"id")+"/parsed="+parsed,()->{
        var c=recipe(record);var matrix=matrix(c,result);if(parsed)matrix=roundTrip(matrix);var replay=object(object(record.get("replay")).get("value"));var got=SignacMotifEnrichment.enrich(matrix,strings(replay.get("effective_query")),strings(replay.get("effective_background")),profile(record),correction(c),100_000_000,()->false);var want=array(result.get("rows"));assertEquals(want.size(),got.rows().size());
        for(int i=0;i<want.size();i++){var expected=object(want.get(i));var row=got.rows().get(i);assertEquals(text(expected,"motif"),row.motif());assertEquals(text(expected,"motif.name"),row.name());equal(expected.get("observed"),row.observed());equal(expected.get("background"),row.background());equal(expected.get("percent.observed"),row.percentObserved());equal(expected.get("percent.background"),row.percentBackground());equal(expected.get("fold.enrichment"),row.foldEnrichment());equal(expected.get("pvalue"),row.pvalue());if(profile(record)==SignacMotifEnrichment.Profile.LEGACY_1_6)assertNull(row.adjustedP());else equal(expected.get("p.adjust"),row.adjustedP());}
        assertEquals(strings(replay.get("effective_query")).size(),got.queryRows());assertEquals(strings(replay.get("effective_background")).size(),got.backgroundRows());assertFalse(got.warnings().isEmpty());
    }));}return tests.stream();}
    @TestFactory Stream<DynamicTest> absentExplicitRowsRetainFailures(){List<DynamicTest> tests=new ArrayList<>();for(Object value:list(original.get("results"))){var record=object(value);if(!Set.of("missing-explicit-query","missing-explicit-background").contains(text(record,"id")))continue;tests.add(DynamicTest.dynamicTest(text(record,"profile")+"/"+text(record,"id"),()->{
        assertTrue(object(object(record.get("result")).get("value")).containsKey("error"));var c=recipe(record);var m=baseMatrix();List<String> query=selected(c.get("query"),m.peaks()),background=selected(c.get("background"),m.peaks());assertThrows(IOException.class,()->SignacMotifEnrichment.enrich(m,query,background,profile(record),correction(c),100000,()->false));
    }));}return tests.stream();}
    @Test void capturedMatrixArraysAreImmutable()throws Exception{var m=baseMatrix();double first=m.values()[0];m.values()[0]=999;m.rows()[0]=999;m.pointers()[0]=99;assertEquals(first,m.values()[0]);assertEquals(0,m.pointers()[0]);assertNotEquals(999,m.rows()[0]);}
    @Test void singleAndZeroMotifsAreSupported()throws Exception{var zero=new SignacMotifEnrichment.Matrix(List.of("p"),List.of(),List.of(),new int[]{0},new int[0],new double[0]);assertTrue(SignacMotifEnrichment.enrich(zero,List.of("p"),null,SignacMotifEnrichment.Profile.CORRECTED_1_7_PLUS,SignacMotifEnrichment.Correction.BH,100,()->false).rows().isEmpty());}
    @Test void patternDuplicateCoordinatesUseLogicalUnion()throws Exception{var r=read("%%MatrixMarket matrix coordinate pattern general\n2 1 3\n1 1\n1 1\n2 1\n");assertEquals(1,r.duplicateCoordinates());assertArrayEquals(new double[]{1,1},r.matrix().values());}
    @Test void numericDuplicatesSumAndKeepStoredZero()throws Exception{var r=read("%%MatrixMarket matrix coordinate integer general\n2 1 3\n1 1 2\n1 1 3\n2 1 0\n");assertEquals(1,r.duplicateCoordinates());assertArrayEquals(new double[]{5,0},r.matrix().values());assertEquals(2,r.matrix().rows().length);}
    @Test void malformedMarketsAreRejected()throws Exception{for(String value:List.of("%%MatrixMarket matrix array real general\n2 1 1\n1 1 2\n","%%MatrixMarket matrix coordinate integer general\n2 1 1\n1 1 1.5\n","%%MatrixMarket matrix coordinate real general\n2 1 1\n1 1 NaN\n","%%MatrixMarket matrix coordinate real general\n2 1 1\n1 1 -1\n","%%MatrixMarket matrix coordinate pattern symmetric\n2 1 1\n1 1\n","%%MatrixMarket matrix coordinate pattern general\n2 1 1\n1 2\n","%%MatrixMarket matrix coordinate pattern general\n2 1 0\n1 1\n"))assertThrows(IOException.class,()->read(value));}
    @Test void malformedUtf8IsRejected()throws Exception{Path folder=folder();Files.writeString(folder.resolve("matrix"),"%%MatrixMarket matrix coordinate pattern general\n2 1 1\n1 1\n");Files.write(folder.resolve("peaks"),new byte[]{(byte)0xff,10,66,10});Files.writeString(folder.resolve("labels"),"motif_id\tmotif_name\nM\tname\n");assertThrows(IOException.class,()->SignacMotifIO.read(folder.resolve("matrix"),folder.resolve("peaks"),folder.resolve("labels"),SignacMotifIO.Limits.defaults(),()->false));}
    @Test void unicodeLabelsRoundTripExactly()throws Exception{var m=new SignacMotifEnrichment.Matrix(List.of("peak α","peak β"),List.of("motif γ"),List.of("TF δ"),new int[]{0,2},new int[]{0,1},new double[]{0,2});var got=roundTrip(m);assertEquals(m.peaks(),got.peaks());assertEquals(m.motifs(),got.motifs());assertEquals(m.names(),got.names());assertArrayEquals(m.values(),got.values());}
    @Test void repeatedOrMismatchedLabelsFail(){assertThrows(IllegalArgumentException.class,()->new SignacMotifEnrichment.Matrix(List.of("p","p"),List.of("M"),List.of("N"),new int[]{0,0},new int[0],new double[0]));assertThrows(IllegalArgumentException.class,()->new SignacMotifEnrichment.Matrix(List.of("p"),List.of("M"),List.of(),new int[]{0,0},new int[0],new double[0]));}
    @Test void cancellationStopsSparseWork()throws Exception{var m=baseMatrix();AtomicInteger checks=new AtomicInteger();assertThrows(CancellationException.class,()->SignacMotifEnrichment.enrich(m,m.peaks().subList(0,12),null,SignacMotifEnrichment.Profile.CORRECTED_1_7_PLUS,SignacMotifEnrichment.Correction.BH,100000,()->checks.incrementAndGet()>100));}
    @Test void explicitWorkCapacityFails()throws Exception{var m=baseMatrix();assertThrows(IllegalArgumentException.class,()->SignacMotifEnrichment.enrich(m,List.of(m.peaks().get(0)),null,SignacMotifEnrichment.Profile.CORRECTED_1_7_PLUS,SignacMotifEnrichment.Correction.BH,1,()->false));}
    @Test void sourceUsesBackgroundAlone(){assertEquals(0,SignacMotifEnrichment.sourceTail(2,0,12,72));assertEquals(1,SignacMotifEnrichment.sourceTail(0,0,12,72));assertTrue(SignacMotifEnrichment.sourceTail(3,14,12,72)>0.4);}
    @Test void invalidSourcePopulationRemainsNaN(){assertTrue(Double.isNaN(SignacMotifEnrichment.sourceTail(2,100,12,72)));assertTrue(Double.isNaN(SignacMotifEnrichment.sourceTail(0,0,12,0)));assertTrue(Double.isNaN(SignacMotifEnrichment.sourceTail(1,2,80,72)));}
    @Test void legacyAndPreparationWarningsAreExplicit()throws Exception{var m=baseMatrix();var r=SignacMotifEnrichment.enrich(m,List.of(m.peaks().get(0)),null,SignacMotifEnrichment.Profile.LEGACY_1_6,SignacMotifEnrichment.Correction.HOMMEL,100000,()->false);assertTrue(r.rows().stream().allMatch(v->v.adjustedP()==null));assertTrue(r.warnings().stream().anyMatch(v->v.startsWith("LEGACY_NO_ADJUSTMENT_COLUMN")));assertTrue(r.warnings().stream().anyMatch(v->v.startsWith("UPSTREAM_PREPARATION_REQUIRED")));}
    @Test void exactDomainAndNegativeCountsAreGuarded(){for(double value:new double[]{-1,0.5,Double.NaN,Double.POSITIVE_INFINITY,9007199254740992.0})assertThrows(IllegalArgumentException.class,()->new SignacMotifEnrichment.Matrix(List.of("p"),List.of("M"),List.of("N"),new int[]{0,1},new int[]{0},new double[]{value}));}
    @Test void originalSamplerReplayStatesAreExact(){int successes=0;for(Object value:list(original.get("results"))){var row=object(value);var result=object(object(row.get("result")).get("value"));if(result.containsKey("error"))continue;successes++;assertEquals(result.get("seed_after"),object(object(row.get("replay")).get("value")).get("replay_after"));}assertEquals(111,successes);}
    private Map<String,Object> recipe(Map<String,Object> record){return list(cases.get("cases")).stream().map(SignacMotifEnrichmentTest::object).filter(v->v.get("id").equals(record.get("id"))).findFirst().orElseThrow();}
    private SignacMotifEnrichment.Matrix baseMatrix(){var record=list(original.get("results")).stream().map(SignacMotifEnrichmentTest::object).filter(v->v.get("id").equals("explicit-BH")&&v.get("profile").equals("1.17.1-package")).findFirst().orElseThrow();return matrix(recipe(record),object(object(record.get("result")).get("value")));}
    private SignacMotifEnrichment.Matrix matrix(Map<String,Object> c,Map<String,Object> result){var d=object(object(cases.get("datasets")).get(c.get("dataset")));List<String> peaks=list(d.get("peaks")).stream().map(SignacMotifEnrichmentTest::object).map(p->text(p,"chromosome")+"-"+((Number)p.get("start")).intValue()+"-"+((Number)p.get("end")).intValue()).toList(),motifs=strings(d.get("motifs"));Map<String,Object> effective=motifs.isEmpty()?Map.of():object(result.get("effective_motif_names"));List<String> names=motifs.stream().map(v->(String)effective.get(v)).toList();int[] pointers=new int[motifs.size()+1];List<Integer> rows=new ArrayList<>();List<Double> values=new ArrayList<>();var source=list(d.get("matrix"));for(int column=0;column<motifs.size();column++){for(int row=0;row<peaks.size();row++){double value=((Number)list(source.get(row)).get(column)).doubleValue();if(value!=0){rows.add(row);values.add(value);}}pointers[column+1]=values.size();}return new SignacMotifEnrichment.Matrix(peaks,motifs,names,pointers,rows.stream().mapToInt(Integer::intValue).toArray(),values.stream().mapToDouble(Double::doubleValue).toArray());}
    private SignacMotifEnrichment.Matrix roundTrip(SignacMotifEnrichment.Matrix m)throws Exception{Path dir=folder();Files.writeString(dir.resolve("peaks"),String.join("\n",m.peaks())+"\n",StandardCharsets.UTF_8);StringBuilder labels=new StringBuilder("motif_id\tmotif_name\n");for(int i=0;i<m.motifs().size();i++)labels.append(m.motifs().get(i)).append('\t').append(m.names().get(i)).append('\n');Files.writeString(dir.resolve("labels"),labels,StandardCharsets.UTF_8);SignacMotifIO.write(m,dir.resolve("matrix"),()->false);return SignacMotifIO.read(dir.resolve("matrix"),dir.resolve("peaks"),dir.resolve("labels"),SignacMotifIO.Limits.defaults(),()->false).matrix();}
    private SignacMotifIO.Input read(String data)throws Exception{Path dir=folder();Files.writeString(dir.resolve("matrix"),data);Files.writeString(dir.resolve("peaks"),"A\nB\n");Files.writeString(dir.resolve("labels"),"motif_id\tmotif_name\nM\tTF\n");return SignacMotifIO.read(dir.resolve("matrix"),dir.resolve("peaks"),dir.resolve("labels"),SignacMotifIO.Limits.defaults(),()->false);}
    private Path folder()throws IOException{return Files.createDirectory(root.resolve("case-"+files.incrementAndGet()));}
    private static List<String> selected(Object value,List<String> peaks){if(value==null)return null;return array(value).stream().map(v->v instanceof Number n?peaks.get(n.intValue()):(String)v).toList();}
    private static SignacMotifEnrichment.Profile profile(Map<String,Object> r){return text(r,"profile").equals("1.6.0-source")?SignacMotifEnrichment.Profile.LEGACY_1_6:SignacMotifEnrichment.Profile.CORRECTED_1_7_PLUS;}
    private static SignacMotifEnrichment.Correction correction(Map<String,Object> c){String method=text(c,"adjustment");return method.equals("invalid")?SignacMotifEnrichment.Correction.NONE:SignacMotifEnrichment.Correction.valueOf(method.equals("fdr")?"BH":method.toUpperCase(Locale.ROOT));}
    private static void equal(Object expected,double actual){double value=expected instanceof Number n?n.doubleValue():expected.equals("Inf")?Double.POSITIVE_INFINITY:expected.equals("-Inf")?Double.NEGATIVE_INFINITY:Double.NaN;if(!Double.isFinite(value))assertEquals(value,actual);else assertEquals(value,actual,Math.max(2e-12,Math.abs(value)*2e-11));}
    private static Map<String,Object> object(Object v){Map<String,Object> result=new LinkedHashMap<>();for(var e:((Map<?,?>)v).entrySet())result.put((String)e.getKey(),e.getValue());return result;}
    private static List<?> list(Object v){return (List<?>)v;}
    private static List<?> array(Object v){return v==null?List.of():v instanceof List<?> l?l:List.of(v);}
    private static List<String> strings(Object v){return array(v).stream().map(String.class::cast).toList();}
    private static String text(Map<String,Object> v,String key){return (String)v.get(key);}
}
